package com.moodtools.hub

internal object LauncherTranslationChunk2 {
    val entries = mapOf(
        "Confirm the update when Android asks." to arrayOf("Kumpirmahin ang update kapag nagtanong ang Android.", "Android\uC5D0\uC11C \uBB3B\uB294 \uC5C5\uB370\uC774\uD2B8\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "Android \u304C\u8981\u6C42\u3057\u305F\u3068\u304D\u306B\u66F4\u65B0\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5728 Android \u63D0\u793A\u65F6\u786E\u8BA4\u66F4\u65B0\u3002", "Confirma la actualizaci\u00F3n cuando Android lo solicite.", "X\u00E1c nh\u1EADn c\u1EADp nh\u1EADt khi Android y\u00EAu c\u1EA7u.", "Konfirmasi pembaruan saat Android meminta.", "Confirme a atualiza\u00E7\u00E3o quando o Android solicitar.", "قم بتأكيد التحديث عندما يطلب منك Android ذلك."),
        "Confirm the {0} uninstall. Installation follows automatically." to arrayOf("Kumpirmahin ang pag-uninstall ng {0}. Awtomatikong susundan ng pag-install.", "{0} \uC81C\uAC70\uB97C \uD655\uC778\uD569\uB2C8\uB2E4. \uC124\uCE58\uAC00 \uC790\uB3D9\uC73C\uB85C \uC774\uC5B4\uC9D1\uB2C8\uB2E4.", "{0} \u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306F\u81EA\u52D5\u3067\u7D9A\u884C\u3055\u308C\u307E\u3059\u3002", "\u786E\u8BA4 {0} \u5378\u8F7D\u3002\u5B89\u88C5\u5C06\u81EA\u52A8\u8FDB\u884C\u3002", "Confirma la desinstalaci\u00F3n de {0}. La instalaci\u00F3n seguir\u00E1 autom\u00E1ticamente.", "X\u00E1c nh\u1EADn g\u1EE1 c\u00E0i \u0111\u1EB7t {0}. Vi\u1EC7c c\u00E0i \u0111\u1EB7t ti\u1EBFp theo s\u1EBD di\u1EC5n ra t\u1EF1 \u0111\u1ED9ng.", "Konfirmasi pencopotan {0}. Pemasangan akan mengikuti secara otomatis.", "Confirme a desinstala\u00E7\u00E3o de {0}. A instala\u00E7\u00E3o seguir\u00E1 automaticamente.", "قم بتأكيد إلغاء تثبيت {0}. يتبع التثبيت تلقائيًا."),
        "Confirm the {0} uninstall. Its Browse add-ons requirements will open next." to arrayOf("Kumpirmahin ang pag-uninstall ng {0}. Susunod na bubukas ang mga requirements sa Browse add-ons.", "{0} \uC81C\uAC70\uB97C \uD655\uC778\uD569\uB2C8\uB2E4. \uB2E4\uC74C\uC73C\uB85C Browse \uC560\uB4DC\uC628 \uC694\uAD6C\uC0AC\uD56D\uC774 \uC5F4\uB9BD\uB2C8\uB2E4.", "{0} \u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u6B21\u306B\u305D\u306E Browse add-ons \u306E\u8981\u4EF6\u304C\u958B\u304D\u307E\u3059\u3002", "\u786E\u8BA4 {0} \u5378\u8F7D\u3002\u5176\u6D4F\u89C8\u63D2\u4EF6\u7684\u8981\u6C42\u5C06\u968F\u540E\u6253\u5F00\u3002", "Confirma la desinstalaci\u00F3n de {0}. Sus requisitos de complementos Browse se abrir\u00E1n a continuaci\u00F3n.", "X\u00E1c nh\u1EADn g\u1EE1 c\u00E0i \u0111\u1EB7t {0}. C\u00E1c y\u00EAu c\u1EA7u v\u1EC1 ti\u1EC7n \u00EDch m\u1EDF r\u1ED9ng Browse s\u1EBD m\u1EDF ti\u1EBFp theo.", "Konfirmasi pencopotan {0}. Persyaratan add-on Browse akan terbuka berikutnya.", "Confirme a desinstala\u00E7\u00E3o de {0}. Os requisitos de complementos Browse ser\u00E3o abertos em seguida.", "قم بتأكيد إلغاء تثبيت {0}. سيتم فتح متطلبات الوظائف الإضافية للتصفح بعد ذلك."),
        "Connect, then tap Try again. Active access on this device will be restored automatically." to arrayOf("Kumonekta, pagkatapos ay i-tap ang Try again. Awtomatikong maibabalik ang aktibong access sa device na ito.", "\uC5F0\uACB0\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4 \uD0ED\uC744 \uB204\uB985\uB2C8\uB2E4. \uC774 \uC7A5\uCE58\uC5D0\uC11C \uD65C\uC131 \uC561\uC138\uC2A4\uAC00 \uC790\uB3D9\uC73C\uB85C \uBCF5\uC6D0\uB429\uB2C8\uB2E4.", "\u63A5\u7D9A\u3057\u3066\u304B\u3089\u300C\u518D\u8A66\u884C\u300D\u3092\u30BF\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u3067\u306E\u30A2\u30AF\u30C6\u30A3\u30D6\u30A2\u30AF\u30BB\u30B9\u306F\u81EA\u52D5\u7684\u306B\u5FA9\u5143\u3055\u308C\u307E\u3059\u3002", "\u8FDE\u63A5\u540E\uFF0C\u70B9\u51FB\u91CD\u8BD5\u3002\u6B64\u8BBE\u5907\u4E0A\u7684\u6D3B\u52A8\u8BBF\u95EE\u6743\u9650\u5C06\u81EA\u52A8\u6062\u590D\u3002", "Con\u00E9ctate, luego toca Intentar de nuevo. El acceso activo en este dispositivo se restaurar\u00E1 autom\u00E1ticamente.", "K\u1EBFt n\u1ED1i, sau \u0111\u00F3 nh\u1EA5n Th\u1EED l\u1EA1i. Quy\u1EC1n truy c\u1EADp \u0111ang ho\u1EA1t \u0111\u1ED9ng tr\u00EAn thi\u1EBFt b\u1ECB n\u00E0y s\u1EBD \u0111\u01B0\u1EE3c kh\u00F4i ph\u1EE5c t\u1EF1 \u0111\u1ED9ng.", "Sambungkan, lalu ketuk Coba lagi. Akses aktif di perangkat ini akan dipulihkan secara otomatis.", "Conecte-se, depois toque em Tentar novamente. O acesso ativo neste dispositivo ser\u00E1 restaurado automaticamente.", "اتصل، ثم اضغط على حاول مرة أخرى. ستتم استعادة الوصول النشط على هذا الجهاز تلقائيًا."),
        "Continue in Google Play" to arrayOf("Magpatuloy sa Google Play", "Google Play\uC5D0\uC11C \uACC4\uC18D\uD558\uAE30", "Google Play\u3067\u7D9A\u884C", "\u5728 Google Play \u4E0A\u7EE7\u7EED", "Continuar en Google Play", "Ti\u1EBFp t\u1EE5c tr\u00EAn Google Play", "Lanjutkan di Google Play", "Continuar no Google Play", "المتابعة في جوجل بلاي"),
        "Could not clear managed data for {0}" to arrayOf("Hindi ma-clear ang managed data para sa {0}", "{0}\uC758 \uAD00\uB9AC \uB370\uC774\uD130\uB97C \uC9C0\uC6B8 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "{0} \u306E\u7BA1\u7406\u30C7\u30FC\u30BF\u3092\u6D88\u53BB\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u6E05\u9664 {0} \u7684\u6258\u7BA1\u6570\u636E", "No se pudo borrar los datos gestionados de {0}", "Kh\u00F4ng th\u1EC3 x\u00F3a d\u1EEF li\u1EC7u qu\u1EA3n l\u00FD cho {0}", "Tidak dapat menghapus data yang dikelola untuk {0}", "N\u00E3o foi poss\u00EDvel limpar os dados gerenciados de {0}", "لا يمكن مسح البيانات المُدارة لـ {0}"),
        "Could not clear previous local test staging for {0}" to arrayOf("Hindi ma-clear ang nakaraang local test staging para sa {0}", "{0}\uC758 \uC774\uC804 \uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uC2A4\uD14C\uC774\uC9D5\uC744 \uC9C0\uC6B8 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "{0} \u306E\u4EE5\u524D\u306E\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30B9\u30C6\u30FC\u30B8\u30F3\u30B0\u3092\u6D88\u53BB\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u6E05\u9664 {0} \u4E4B\u524D\u7684\u672C\u5730\u6D4B\u8BD5\u6682\u5B58", "No se pudo borrar el entorno de prueba local anterior de {0}", "Kh\u00F4ng th\u1EC3 x\u00F3a giai \u0111o\u1EA1n th\u1EED nghi\u1EC7m c\u1EE5c b\u1ED9 tr\u01B0\u1EDBc \u0111\u00F3 cho {0}", "Tidak dapat menghapus staging tes lokal sebelumnya untuk {0}", "N\u00E3o foi poss\u00EDvel limpar o staging de teste local anterior de {0}", "تعذر مسح مرحلة الاختبار المحلي السابقة لـ {0}"),
        "Could not clear stale {0} shell material; preparation will replace it." to arrayOf("Hindi ma-clear ang lumang {0} shell material; papalitan ito ng paghahanda.", "\uC624\uB798\uB41C {0} \uC178 \uC790\uB8CC\uB97C \uC9C0\uC6B8 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4; \uC900\uBE44 \uACFC\uC815\uC5D0\uC11C \uC774\uB97C \uAD50\uCCB4\uD569\uB2C8\uB2E4.", "\u53E4\u3044 {0} \u30B7\u30A7\u30EB\u30DE\u30C6\u30EA\u30A2\u30EB\u3092\u6D88\u53BB\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\uFF1B\u6E96\u5099\u3067\u7F6E\u304D\u63DB\u3048\u307E\u3059", "\u65E0\u6CD5\u6E05\u9664\u8FC7\u671F\u7684 {0} \u5916\u58F3\u6750\u6599\uFF1B\u51C6\u5907\u9636\u6BB5\u5C06\u66FF\u6362\u5B83\u3002", "No se pudo borrar el material de shell obsoleto {0}; la preparaci\u00F3n lo reemplazar\u00E1.", "Kh\u00F4ng th\u1EC3 x\u00F3a v\u1EADt li\u1EC7u v\u1ECF {0} c\u0169; vi\u1EC7c chu\u1EA9n b\u1ECB s\u1EBD thay th\u1EBF n\u00F3.", "Tidak dapat menghapus materi shell {0} yang usang; persiapan akan menggantinya.", "N\u00E3o foi poss\u00EDvel limpar o material de shell obsoleto {0}; a prepara\u00E7\u00E3o o substituir\u00E1.", "لا يمكن مسح مادة الغلاف {0} القديمة؛ التحضير سوف يحل محله."),
        "Could not commit local test module {0}" to arrayOf("Hindi ma-commit ang local test module {0}", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uBAA8\uB4C8 {0}\uC744(\uB97C) \uCEE4\uBC0B\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30E2\u30B8\u30E5\u30FC\u30EB {0} \u3092\u30B3\u30DF\u30C3\u30C8\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u63D0\u4EA4\u672C\u5730\u6D4B\u8BD5\u6A21\u5757 {0}", "No se pudo confirmar el m\u00F3dulo de prueba local {0}", "Kh\u00F4ng th\u1EC3 cam k\u1EBFt m\u00F4-\u0111un th\u1EED nghi\u1EC7m c\u1EE5c b\u1ED9 {0}", "Tidak dapat mengkomit modul tes lokal {0}", "N\u00E3o foi poss\u00EDvel confirmar o m\u00F3dulo de teste local {0}", "لا يمكن تنفيذ وحدة الاختبار المحلية {0}"),
        "Could not create local test staging for {0}" to arrayOf("Hindi makalikha ng local test staging para sa {0}", "{0}\uC758 \uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uC2A4\uD14C\uC774\uC9D5\uC744 \uC0DD\uC131\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "{0} \u306E\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30B9\u30C6\u30FC\u30B8\u30F3\u30B0\u3092\u4F5C\u6210\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u4E3A {0} \u521B\u5EFA\u672C\u5730\u6D4B\u8BD5\u6682\u5B58", "No se pudo crear el entorno de prueba local para {0}", "Kh\u00F4ng th\u1EC3 t\u1EA1o giai \u0111o\u1EA1n th\u1EED nghi\u1EC7m c\u1EE5c b\u1ED9 cho {0}", "Tidak dapat membuat staging tes lokal untuk {0}", "N\u00E3o foi poss\u00EDvel criar staging de teste local para {0}", "تعذر إنشاء مرحلة اختبار محلية لـ {0}"),
        "Could not open the unlock web route" to arrayOf("Hindi ma-open ang unlock web route", "\uC7A0\uAE08 \uD574\uC81C \uC6F9 \uACBD\uB85C\uB97C \uC5F4 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A2\u30F3\u30ED\u30C3\u30AFWeb\u30EB\u30FC\u30C8\u3092\u958B\u3051\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u6253\u5F00\u89E3\u9501\u7F51\u9875\u8DEF\u5F84", "No se pudo abrir la ruta web de desbloqueo", "Kh\u00F4ng th\u1EC3 m\u1EDF \u0111\u01B0\u1EDDng d\u1EABn web m\u1EDF kh\u00F3a", "Tidak dapat membuka rute web pembukaan kunci", "N\u00E3o foi poss\u00EDvel abrir a rota de desbloqueio na web", "تعذر فتح مسار فتح الويب"),
        "Could not prepare replacement package" to arrayOf("Hindi maihanda ang replacement package", "\uAD50\uCCB4 \uD328\uD0A4\uC9C0\uB97C \uC900\uBE44\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u7F6E\u63DB\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u6E96\u5099\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u51C6\u5907\u66FF\u6362\u5305", "No se pudo preparar el paquete de reemplazo", "Kh\u00F4ng th\u1EC3 chu\u1EA9n b\u1ECB g\u00F3i thay th\u1EBF", "Tidak dapat menyiapkan paket pengganti", "N\u00E3o foi poss\u00EDvel preparar o pacote de substitui\u00E7\u00E3o", "تعذر إعداد الحزمة البديلة"),
        "Could not refresh Play Store versions" to arrayOf("Hindi ma-refresh ang mga bersyon sa Play Store", "Play \uC2A4\uD1A0\uC5B4 \uBC84\uC804\uC744 \uC0C8\uB85C \uACE0\uCE60 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "Play\u30B9\u30C8\u30A2\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u3092\u66F4\u65B0\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u5237\u65B0 Play \u5546\u5E97\u7248\u672C", "No se pudieron actualizar las versiones de Play Store", "Kh\u00F4ng th\u1EC3 l\u00E0m m\u1EDBi c\u00E1c phi\u00EAn b\u1EA3n tr\u00EAn Play Store", "Tidak dapat menyegarkan versi Play Store", "N\u00E3o foi poss\u00EDvel atualizar as vers\u00F5es da Play Store", "تعذر تحديث إصدارات متجر Play"),
        "Could not replace existing module {0}" to arrayOf("Hindi mapapalitan ang existing module {0}", "\uAE30\uC874 \uBAA8\uB4C8 {0}\uC744(\uB97C) \uAD50\uCCB4\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u65E2\u5B58\u306E\u30E2\u30B8\u30E5\u30FC\u30EB {0} \u3092\u7F6E\u304D\u63DB\u3048\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u66FF\u6362\u73B0\u6709\u6A21\u5757 {0}", "No se pudo reemplazar el m\u00F3dulo existente {0}", "Kh\u00F4ng th\u1EC3 thay th\u1EBF m\u00F4-\u0111un hi\u1EC7n c\u00F3 {0}", "Tidak dapat mengganti modul {0} yang ada", "N\u00E3o foi poss\u00EDvel substituir o m\u00F3dulo existente {0}", "لا يمكن استبدال الوحدة الموجودة {0}"),
        "Could not start package install" to arrayOf("Hindi masimulan ang pag-install ng package", "\uD328\uD0A4\uC9C0 \uC124\uCE58\uB97C \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30D1\u30C3\u30B1\u30FC\u30B8\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u958B\u59CB\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u542F\u52A8\u5305\u5B89\u88C5", "No se pudo iniciar la instalaci\u00F3n del paquete", "Kh\u00F4ng th\u1EC3 b\u1EAFt \u0111\u1EA7u c\u00E0i \u0111\u1EB7t g\u00F3i", "Tidak dapat memulai pemasangan paket", "N\u00E3o foi poss\u00EDvel iniciar a instala\u00E7\u00E3o do pacote", "تعذر بدء تثبيت الحزمة"),
