        "Couldn't check for updates" to arrayOf("Hindi ma-check para sa mga update", "\uC5C5\uB370\uC774\uD2B8\uB97C \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u66F4\u65B0\u3092\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u68C0\u67E5\u66F4\u65B0", "No se pudo buscar actualizaciones", "Kh\u00F4ng th\u1EC3 ki\u1EC3m tra b\u1EA3n c\u1EADp nh\u1EADt", "Tidak dapat memeriksa pembaruan", "N\u00E3o foi poss\u00EDvel verificar atualiza\u00E7\u00F5es", "تعذر التحقق من وجود تحديثات"),
        "Couldn't check your access" to arrayOf("Hindi ma-check ang iyong access", "\uC811\uADFC \uAD8C\uD55C\uC744 \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A2\u30AF\u30BB\u30B9\u3092\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u68C0\u67E5\u60A8\u7684\u8BBF\u95EE\u6743\u9650", "No se pudo comprobar su acceso", "Kh\u00F4ng th\u1EC3 ki\u1EC3m tra quy\u1EC1n truy c\u1EADp c\u1EE7a b\u1EA1n", "Tidak dapat memeriksa akses Anda", "N\u00E3o foi poss\u00EDvel verificar seu acesso", "تعذر التحقق من وصولك"),
        "Couldn't clear game data" to arrayOf("Hindi ma-clear ang game data", "\uAC8C\uC784 \uB370\uC774\uD130\uB97C \uC9C0\uC6B8 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30B2\u30FC\u30E0\u30C7\u30FC\u30BF\u3092\u6D88\u53BB\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u6E05\u9664\u6E38\u620F\u6570\u636E", "No se pudieron borrar los datos del juego", "Kh\u00F4ng th\u1EC3 x\u00F3a d\u1EEF li\u1EC7u tr\u00F2 ch\u01A1i", "Tidak dapat menghapus data game", "N\u00E3o foi poss\u00EDvel limpar os dados do jogo", "لا يمكن مسح بيانات اللعبة"),
        "Couldn't download the add-on" to arrayOf("Hindi ma-download ang add-on", "\uC560\uB4DC\uC628\uC744 \uB2E4\uC6B4\uB85C\uB4DC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A2\u30C9\u30AA\u30F3\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u4E0B\u8F7D\u9644\u52A0\u7EC4\u4EF6", "No se pudo descargar el complemento", "Kh\u00F4ng th\u1EC3 t\u1EA3i xu\u1ED1ng ti\u1EC7n \u00EDch b\u1ED5 sung", "Tidak dapat mengunduh add-on", "N\u00E3o foi poss\u00EDvel baixar o complemento", "تعذر تنزيل الوظيفة الإضافية"),
        "Couldn't download the game" to arrayOf("Hindi ma-download ang laro", "\uAC8C\uC784\uC744 \uB2E4\uC6B4\uB85C\uB4DC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30B2\u30FC\u30E0\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u4E0B\u8F7D\u6E38\u620F", "No se pudo descargar el juego", "Kh\u00F4ng th\u1EC3 t\u1EA3i game", "Tidak bisa mengunduh permainan", "N\u00E3o foi poss\u00EDvel baixar o jogo", "تعذر تنزيل اللعبة"),
        "Couldn't download the launcher update" to arrayOf("Hindi ma-download ang update ng launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8\uB97C \uB2E4\uC6B4\uB85C\uB4DC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u4E0B\u8F7D\u542F\u52A8\u5668\u66F4\u65B0", "No se pudo descargar la actualizaci\u00F3n del lanzador", "Kh\u00F4ng th\u1EC3 t\u1EA3i b\u1EA3n c\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y", "Tidak bisa mengunduh pembaruan launcher", "N\u00E3o foi poss\u00EDvel baixar a atualiza\u00E7\u00E3o do inicializador", "تعذر تنزيل تحديث المشغل"),
        "Couldn't open Google Play" to arrayOf("Hindi mabuksan ang Google Play", "Google Play\uB97C \uC5F4 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "Google Play\u3092\u958B\u3051\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u6253\u5F00 Google Play", "No se pudo abrir Google Play", "Kh\u00F4ng th\u1EC3 m\u1EDF Google Play", "Tidak bisa membuka Google Play", "N\u00E3o foi poss\u00EDvel abrir o Google Play", "تعذر فتح Google Play"),
        "Couldn't open the game" to arrayOf("Hindi mabuksan ang laro", "\uAC8C\uC784\uC744 \uC5F4 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30B2\u30FC\u30E0\u3092\u958B\u3051\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u6253\u5F00\u6E38\u620F", "No se pudo abrir el juego", "Kh\u00F4ng th\u1EC3 m\u1EDF game", "Tidak bisa membuka permainan", "N\u00E3o foi poss\u00EDvel abrir o jogo", "لا يمكن فتح اللعبة"),
        "Couldn't open the installer" to arrayOf("Hindi mabuksan ang installer", "\uC124\uCE58 \uAD00\uB9AC\uC790\uB97C \uC5F4 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u958B\u3051\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u6253\u5F00\u5B89\u88C5\u7A0B\u5E8F", "No se pudo abrir el instalador", "Kh\u00F4ng th\u1EC3 m\u1EDF tr\u00ECnh c\u00E0i \u0111\u1EB7t", "Tidak bisa membuka installer", "N\u00E3o foi poss\u00EDvel abrir o instalador", "لا يمكن فتح المثبت"),
        "Couldn't prepare setup storage" to arrayOf("Hindi maihanda ang setup storage", "\uC124\uCE58 \uC800\uC7A5\uC18C\uB97C \uC900\uBE44\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u30B9\u30C8\u30EC\u30FC\u30B8\u3092\u6E96\u5099\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u51C6\u5907\u5B89\u88C5\u5B58\u50A8", "No se pudo preparar el almacenamiento de configuraci\u00F3n", "Kh\u00F4ng th\u1EC3 chu\u1EA9n b\u1ECB dung l\u01B0\u1EE3ng c\u00E0i \u0111\u1EB7t", "Tidak bisa menyiapkan ruang penyimpanan setup", "N\u00E3o foi poss\u00EDvel preparar o armazenamento de configura\u00E7\u00E3o", "تعذر إعداد مساحة تخزين الإعداد"),
        "Couldn't prepare the game setup" to arrayOf("Hindi maihanda ang setup ng laro", "\uAC8C\uC784 \uC124\uCE58\uB97C \uC900\uBE44\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30B2\u30FC\u30E0\u306E\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u3092\u6E96\u5099\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u51C6\u5907\u6E38\u620F\u5B89\u88C5", "No se pudo preparar la instalaci\u00F3n del juego", "Kh\u00F4ng th\u1EC3 chu\u1EA9n b\u1ECB c\u00E0i \u0111\u1EB7t game", "Tidak bisa menyiapkan setup permainan", "N\u00E3o foi poss\u00EDvel preparar a configura\u00E7\u00E3o do jogo", "تعذر إعداد إعداد اللعبة"),
        "Couldn't reach the download service" to arrayOf("Hindi maabot ang download service", "\uB2E4\uC6B4\uB85C\uB4DC \uC11C\uBE44\uC2A4\uC5D0 \uC5F0\uACB0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u30B5\u30FC\u30D3\u30B9\u306B\u63A5\u7D9A\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u8FDE\u63A5\u4E0B\u8F7D\u670D\u52A1", "No se pudo acceder al servicio de descarga", "Kh\u00F4ng th\u1EC3 k\u1EBFt n\u1ED1i v\u1EDBi d\u1ECBch v\u1EE5 t\u1EA3i xu\u1ED1ng", "Tidak bisa mengakses layanan unduhan", "N\u00E3o foi poss\u00EDvel acessar o servi\u00E7o de download", "تعذر الوصول إلى خدمة التنزيل"),
        "Couldn't reach the update service" to arrayOf("Hindi maabot ang update service", "\uC5C5\uB370\uC774\uD2B8 \uC11C\uBE44\uC2A4\uC5D0 \uC5F0\uACB0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u66F4\u65B0\u30B5\u30FC\u30D3\u30B9\u306B\u63A5\u7D9A\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u8FDE\u63A5\u66F4\u65B0\u670D\u52A1", "No se pudo acceder al servicio de actualizaci\u00F3n", "Kh\u00F4ng th\u1EC3 k\u1EBFt n\u1ED1i v\u1EDBi d\u1ECBch v\u1EE5 c\u1EADp nh\u1EADt", "Tidak bisa mengakses layanan pembaruan", "N\u00E3o foi poss\u00EDvel acessar o servi\u00E7o de atualiza\u00E7\u00E3o", "تعذر الوصول إلى خدمة التحديث"),
        "Couldn't remove one add-on" to arrayOf("Hindi maalis ang isang add-on", "\uD558\uB098\uC758 \uCD94\uAC00 \uAE30\uB2A5\uC744 \uC81C\uAC70\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "1\u3064\u306E\u30A2\u30C9\u30AA\u30F3\u3092\u524A\u9664\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u79FB\u9664\u4E00\u4E2A\u63D2\u4EF6", "No se pudo eliminar un complemento", "Kh\u00F4ng th\u1EC3 g\u1EE1 b\u1ECF m\u1ED9t ti\u1EC7n \u00EDch b\u1ED5 sung", "Tidak bisa menghapus satu add-on", "N\u00E3o foi poss\u00EDvel remover um complemento", "تعذرت إزالة وظيفة إضافية واحدة"),
        "Couldn't remove {0} add-ons" to arrayOf("Hindi maalis ang {0} add-on", "{0}\uAC1C\uC758 \uCD94\uAC00 \uAE30\uB2A5\uC744 \uC81C\uAC70\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "{0}\u500B\u306E\u30A2\u30C9\u30AA\u30F3\u3092\u524A\u9664\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u79FB\u9664 {0} \u4E2A\u63D2\u4EF6", "No se pudieron eliminar {0} complementos", "Kh\u00F4ng th\u1EC3 g\u1EE1 b\u1ECF {0} ti\u1EC7n \u00EDch b\u1ED5 sung", "Tidak bisa menghapus {0} add-on", "N\u00E3o foi poss\u00EDvel remover {0} complementos", "تعذرت إزالة {0} من الإضافات"),
        "Couldn't repair the add-on" to arrayOf("Hindi maayos ang add-on", "\uCD94\uAC00 \uAE30\uB2A5\uC744 \uC218\uB9AC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A2\u30C9\u30AA\u30F3\u3092\u4FEE\u5FA9\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u4FEE\u590D\u63D2\u4EF6", "No se pudo reparar el complemento", "Kh\u00F4ng th\u1EC3 s\u1EEDa ti\u1EC7n \u00EDch b\u1ED5 sung", "Tidak bisa memperbaiki add-on", "N\u00E3o foi poss\u00EDvel reparar o complemento", "تعذر إصلاح الوظيفة الإضافية"),
        "Couldn't save the download" to arrayOf("Hindi masave ang download", "\uB2E4\uC6B4\uB85C\uB4DC\uB97C \uC800\uC7A5\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u4FDD\u5B58\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u4FDD\u5B58\u4E0B\u8F7D\u5185\u5BB9", "No se pudo guardar la descarga", "Kh\u00F4ng th\u1EC3 l\u01B0u t\u1EA3i xu\u1ED1ng", "Tidak bisa menyimpan unduhan", "N\u00E3o foi poss\u00EDvel salvar o download", "تعذر حفظ التنزيل"),
        "Couldn't stage local test module" to arrayOf("Hindi ma-stage ang local test module", "\uB85C\uCEEC \uD14C\uC2A4\uD2B8 \uBAA8\uB4C8\uC744 \uB2E8\uACC4\uD654\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30ED\u30FC\u30AB\u30EB\u30C6\u30B9\u30C8\u30E2\u30B8\u30E5\u30FC\u30EB\u3092\u30B9\u30C6\u30FC\u30B8\u30F3\u30B0\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u6682\u5B58\u672C\u5730\u6D4B\u8BD5\u6A21\u5757", "No se pudo preparar el m\u00F3dulo de prueba local", "Kh\u00F4ng th\u1EC3 chu\u1EA9n b\u1ECB m\u00F4-\u0111un ki\u1EC3m tra c\u1EE5c b\u1ED9", "Tidak bisa menempatkan modul tes lokal", "N\u00E3o foi poss\u00EDvel preparar o m\u00F3dulo de teste local", "تعذر تنظيم وحدة الاختبار المحلية"),
        "Couldn't update the add-on" to arrayOf("Hindi ma-update ang add-on", "\uCD94\uAC00 \uAE30\uB2A5\uC744 \uC5C5\uB370\uC774\uD2B8\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A2\u30C9\u30AA\u30F3\u3092\u66F4\u65B0\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u66F4\u65B0\u63D2\u4EF6", "No se pudo actualizar el complemento", "Kh\u00F4ng th\u1EC3 c\u1EADp nh\u1EADt ti\u1EC7n \u00EDch b\u1ED5 sung", "Tidak bisa memperbarui add-on", "N\u00E3o foi poss\u00EDvel atualizar o complemento", "تعذر تحديث الوظيفة الإضافية"),
        "Create & install" to arrayOf("Gumawa at i-install", "\uC0DD\uC131 \uBC0F \uC124\uCE58", "\u4F5C\u6210\u3057\u3066\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB", "\u521B\u5EFA\u5E76\u5B89\u88C5", "Crear e instalar", "T\u1EA1o & c\u00E0i \u0111\u1EB7t", "Buat & pasang", "Criar & instalar", "إنشاء وتثبيت"),
        "Creating an in-place patch update that keeps the installed game's local data." to arrayOf("Gumagawa ng in-place patch update na pinapanatili ang lokal na data ng naka-install na laro.", "\uC124\uCE58\uB41C \uAC8C\uC784\uC758 \uB85C\uCEEC \uB370\uC774\uD130\uB97C \uC720\uC9C0\uD558\uBA74\uC11C \uC81C\uC790\uB9AC \uD328\uCE58 \uC5C5\uB370\uC774\uD2B8\uB97C \uC0DD\uC131\uD558\uACE0 \uC788\uC2B5\uB2C8\uB2E4.", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u306E\u30B2\u30FC\u30E0\u306E\u30ED\u30FC\u30AB\u30EB\u30C7\u30FC\u30BF\u3092\u4FDD\u6301\u3059\u308B\u30A4\u30F3\u30D7\u30EC\u30FC\u30B9\u30D1\u30C3\u30C1\u66F4\u65B0\u3092\u4F5C\u6210\u3057\u3066\u3044\u307E\u3059\u3002", "\u521B\u5EFA\u4E00\u4E2A\u539F\u5730\u8865\u4E01\u66F4\u65B0\uFF0C\u540C\u65F6\u4FDD\u7559\u5DF2\u5B89\u88C5\u6E38\u620F\u7684\u672C\u5730\u6570\u636E\u3002", "Creando una actualizaci\u00F3n de parche in situ que conserva los datos locales del juego instalado.", "T\u1EA1o b\u1EA3n v\u00E1 t\u1EA1i ch\u1ED7 gi\u1EEF nguy\u00EAn d\u1EEF li\u1EC7u c\u1EE5c b\u1ED9 c\u1EE7a game \u0111\u00E3 c\u00E0i \u0111\u1EB7t.", "Membuat pembaruan patch di tempat yang mempertahankan data lokal permainan yang terpasang.", "Criando uma atualiza\u00E7\u00E3o de patch no local que mant\u00E9m os dados locais do jogo instalado.", "إنشاء تحديث تصحيح موضعي يحافظ على البيانات المحلية للعبة المثبتة."),
        "Creating the patched non-root package before Android removes anything." to arrayOf("Lumilikha ng patched non-root package bago tanggalin ng Android ang anumang bagay.", "Android\uAC00 \uC544\uBB34\uAC83\uB3C4 \uC81C\uAC70\uD558\uAE30 \uC804\uC5D0 \uD328\uCE58\uB41C \uBE44\uB8E8\uD2B8 \uD328\uD0A4\uC9C0\uB97C \uC0DD\uC131\uD569\uB2C8\uB2E4.", "Android\u304C\u4F55\u3082\u524A\u9664\u3059\u308B\u524D\u306B\u30D1\u30C3\u30C1\u6E08\u307F\u306E\u975E\u30EB\u30FC\u30C8\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u4F5C\u6210\u3057\u3066\u3044\u307E\u3059\u3002", "\u5728 Android \u79FB\u9664\u4EFB\u4F55\u5185\u5BB9\u4E4B\u524D\u521B\u5EFA\u5DF2\u4FEE\u8865\u7684\u975E root \u5305\u3002", "Creando el paquete no-root parcheado antes de que Android elimine cualquier cosa.", "T\u1EA1o g\u00F3i kh\u00F4ng root \u0111\u00E3 v\u00E1 tr\u01B0\u1EDBc khi Android x\u00F3a b\u1EA5t c\u1EE9 th\u1EE9 g\u00EC.", "Membuat paket non-root yang sudah ditambal sebelum Android menghapus apa pun.", "Criando o pacote n\u00E3o-root com patch antes que o Android remova qualquer coisa.", "إنشاء الحزمة المصححة غير الجذرية قبل أن يقوم Android بإزالة أي شيء."),
        "Debug preview release" to arrayOf("Debug preview release", "\uB514\uBC84\uADF8 \uBBF8\uB9AC\uBCF4\uAE30 \uB9B4\uB9AC\uC2A4", "\u30C7\u30D0\u30C3\u30B0\u30D7\u30EC\u30D3\u30E5\u30FC\u30D0\u30FC\u30B8\u30E7\u30F3", "\u8C03\u8BD5\u9884\u89C8\u7248\u672C", "Vista previa de depuraci\u00F3n", "Ph\u00E1t h\u00E0nh b\u1EA3n xem tr\u01B0\u1EDBc g\u1EE1 l\u1ED7i", "Pratinjau rilis debug", "Vers\u00E3o de pr\u00E9-visualiza\u00E7\u00E3o de depura\u00E7\u00E3o", "إصدار معاينة التصحيح"),
        "Design preview triggered by the debug launcher." to arrayOf("Design preview na sinimulan ng debug launcher.", "\uB514\uBC84\uADF8 \uB7F0\uCC98\uC5D0 \uC758\uD574 \uB514\uC790\uC778 \uBBF8\uB9AC\uBCF4\uAE30\uAC00 \uC2DC\uC791\uB418\uC5C8\uC2B5\uB2C8\uB2E4.", "\u30C7\u30D0\u30C3\u30B0\u30E9\u30F3\u30C1\u30E3\u30FC\u306B\u3088\u3063\u3066\u30C7\u30B6\u30A4\u30F3\u30D7\u30EC\u30D3\u30E5\u30FC\u304C\u30C8\u30EA\u30AC\u30FC\u3055\u308C\u307E\u3057\u305F\u3002", "\u7531\u8C03\u8BD5\u542F\u52A8\u5668\u89E6\u53D1\u7684\u8BBE\u8BA1\u9884\u89C8\u3002", "Vista previa de dise\u00F1o activada por el lanzador de depuraci\u00F3n.", "Xem tr\u01B0\u1EDBc thi\u1EBFt k\u1EBF \u0111\u01B0\u1EE3c k\u00EDch ho\u1EA1t b\u1EDFi tr\u00ECnh kh\u1EDFi ch\u1EA1y g\u1EE1 l\u1ED7i.", "Pratinjau desain dipicu oleh peluncur debug.", "Pr\u00E9-visualiza\u00E7\u00E3o de design acionada pelo lan\u00E7ador de depura\u00E7\u00E3o.", "يتم تشغيل معاينة التصميم بواسطة مشغل تصحيح الأخطاء."),
    )
}
